 function booking(){if(state.busy)return;const dest=state.inPark?'Willow Island':'U-Speak Roblox テーマパーク';openDialog(`<span class="npc-tag">U-SPEAK AIR · ISLAND HOPPER</span><h2>${dest}</h2><p>海を越えて、もうひとつの島へ。フライトは約18秒です。</p><div class="boarding-pass"><small>${state.inPark?'WONDER PARK':'WILLOW ISLAND'}</small><b>✈</b><small>${state.inPark?'WILLOW ISLAND':'WONDER PARK'}</small></div><div class="speech"><strong>One ticket to ${state.inPark?'Willow Island':'the theme park'}, please.</strong><p>${state.inPark?'ウィロー島':'テーマパーク'}までのチケットを1枚ください。</p><button id="flight-listen">▷ 英語を聞く</button></div><button class="primary" id="board-plane">搭乗して出発する →</button>`);$('#flight-listen').onclick=()=>speak(`One ticket to ${state.inPark?'Willow Island':'the theme park'}, please.`);$('#board-plane').onclick=beginFlight}
 function beginFlight(){state.returning=state.inPark;learn(`One ticket to ${state.inPark?'Willow Island':'the theme park'}, please.`,`${state.inPark?'ウィロー島':'テーマパーク'}までのチケットを1枚ください。`);dialog.close();atmosphere.state.firstPerson=false;document.body.classList.remove('first-person');$('#view-toggle').textContent='⌖ 俯瞰';state.busy=true;state.mode='flight';state.elapsed=0;const a=state.returning?end:start,b=state.returning?start:end;flightPath=new THREE.CatmullRomCurve3([a.clone(),a.clone().add(new THREE.Vector3(state.returning?-15:15,14,-13)),new THREE.Vector3(86,35,-6),b.clone().add(new THREE.Vector3(state.returning?12:-12,10,12)),b.clone()]);document.body.classList.add('on-journey');hud.hidden=false;$('#travel-title').textContent=state.returning?'Willow Island へ':'U-Speak Roblox テーマパークへ';$('#travel-action').textContent='到着までスキップ';$('#travel-action').onclick=land;plane.visible=true;speak('Welcome aboard! Enjoy your flight.');}
 function land(silent=false){state.inPark=!state.returning;state.busy=false;state.mode='walk';player.position.set(state.inPark?X+15:18,0,state.inPark?23:16);plane.position.copy(state.inPark?end:start);plane.rotation.set(0,state.inPark?0:-Math.PI/2,0);hud.hidden=true;document.body.classList.remove('on-journey');document.body.classList.toggle('in-park',state.inPark);panel.hidden=!state.inPark;flightButton.innerHTML=state.inPark?'✈ ウィロー島へ帰る':'✈ テーマパークへ';$('.location').innerHTML=state.inPark?'<span>✦</span> WONDER PARK <small>U-Speak Roblox テーマパーク</small>':'<span>✦</span> WILLOW ISLAND <small>はじまりの島</small>';$('.map-panel>div b').textContent=state.inPark?'WONDER PARK':'WILLOW ISLAND';$('#area').textContent=state.inPark?'Arrival plaza':'Village square';if(!silent)toast(state.inPark?'U-Speak Roblox テーマパークへようこそ！':'ウィロー島に到着しました。');camera.position.set(player.position.x+18,22,player.position.z+26)}
 const entrances={wheel:[-18,1],coaster:[16,5],carousel:[-3,-2]};
